using System;using System.Linq;using System.IO;using Mono.Cecil;using Mono.Cecil.Cil;public static class PrepareTf2Libraries{public static void Main(string[] a){using(var m=ModuleDefinition.ReadModule(a[0])){foreach(var t in m.GetTypes())foreach(var method in t.Methods.Where(x=>x.HasBody))foreach(var i in method.Body.Instructions)if(i.OpCode==OpCodes.Ldstr)i.Operand=((string)i.Operand).Replace("TF2SpectatorRCON","ShenPulseRCON").Replace("tf2spectatorbackup","shenpulsebackup").Replace("TF2 Spectator","ShenPulse").Replace("Crowd Control","ShenPulse");m.Write(a[1]);}}}